import{_ as e,c as r,o,a2 as s}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Contacto","description":"Obtenga ayuda con qDiff por correo electrónico y descubra qué datos incluir para que podamos ayudarle con rapidez.","frontmatter":{"title":"Contacto","description":"Obtenga ayuda con qDiff por correo electrónico y descubra qué datos incluir para que podamos ayudarle con rapidez."},"headers":[],"relativePath":"es/guide/support.md","filePath":"es/guide/support.md","lastUpdated":1794296122000}'),t={name:"es/guide/support.md"};function n(i,a,l,c,u,d){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h1><p>Algo que no se entiende, un archivo que no se abre, una idea para la próxima versión: leemos todos los mensajes.</p><p><strong>Correo:</strong> <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a></p><p>Puedes escribirnos en español o en inglés.</p><h2 id="que-nos-ayuda-a-ayudarle" tabindex="-1">Qué nos ayuda a ayudarle <a class="header-anchor" href="#que-nos-ayuda-a-ayudarle" aria-label="Permalink to &quot;Qué nos ayuda a ayudarle&quot;">​</a></h2><ul><li>Su versión de macOS y el modelo de Mac que utiliza.</li><li>La versión de qDiff (abra <strong>Acerca de qDiff</strong> en el menú de la aplicación).</li><li>Qué estaba comparando y qué esperaba ver.</li><li>Una captura de pantalla, si el problema se ve en pantalla.</li></ul><p>Le rogamos que no adjunte archivos que prefiera no compartir: con una descripción o una captura recortada suele ser suficiente.</p><h2 id="antes-de-escribirnos" tabindex="-1">Antes de escribirnos <a class="header-anchor" href="#antes-de-escribirnos" aria-label="Permalink to &quot;Antes de escribirnos&quot;">​</a></h2><p>Las <a href="./faq.html">preguntas frecuentes</a> responden a las dudas más habituales y la <a href="./introduction.html">introducción</a> le guía en la primera comparación. Si su pregunta es sobre privacidad, la <a href="./../privacy/">Política de Privacidad</a> explica con exactitud qué lee y qué no lee qDiff.</p><h2 id="sobre-compras-y-reembolsos" tabindex="-1">Sobre compras y reembolsos <a class="header-anchor" href="#sobre-compras-y-reembolsos" aria-label="Permalink to &quot;Sobre compras y reembolsos&quot;">​</a></h2><p>Las compras y los reembolsos los gestionan el Mac App Store y su Apple ID. Para cuestiones de facturación, el Soporte de Apple es la vía más rápida; para restaurar una compra dentro de qDiff, consulte las <a href="./faq.html">preguntas frecuentes</a>.</p>',11)])])}const f=e(t,[["render",n]]);export{m as __pageData,f as default};
